    def list_recoverable_agent_workers(
        self,
        *,
        limit: int = 100,
        stale_after_seconds: int = 300,
        lane_id: str = "",
        job_id: str = "",
    ) -> list[dict[str, Any]]:
        if self._control_plane_postgres_should_prefer_read("agent_worker_runs"):
            rows = self._call_control_plane_postgres_native(
                "list_recoverable_agent_workers",
                limit=limit,
                stale_after_seconds=stale_after_seconds,
                lane_id=lane_id,
                job_id=job_id,
            )
            return [self._agent_worker_from_row(row) for row in list(rows or [])]
        clauses = [
            "("
            "(status IN ('queued', 'interrupted', 'failed')) "
            "OR (status = 'running' AND json_extract(checkpoint_json, '$.stage') IN ('submitting_remote_search', 'submitting_remote_harvest', 'waiting_remote_search', 'waiting_remote_harvest', 'persisting_terminal_harvest_profiles')) "
            "OR (status = 'running' AND datetime(updated_at) <= datetime('now', ?))"
            ")",
        ]
        params: list[Any] = [f"-{max(1, int(stale_after_seconds or 300))} seconds"]
        if job_id:
            clauses.append("job_id = ?")
            params.append(job_id)
        if lane_id:
            clauses.append("lane_id = ?")
            params.append(lane_id)
        query = (
            "SELECT * FROM agent_worker_runs WHERE "
            + " AND ".join(clauses)
            + " ORDER BY updated_at ASC, worker_id ASC LIMIT ?"
        )
        params.append(max(1, int(limit or 100)))
        with self._lock:
            rows = self._connection.execute(query, tuple(params)).fetchall()
        workers = []
        for row in rows:
            worker = self._agent_worker_from_row(row)
            checkpoint_stage = str(dict(worker.get("checkpoint") or {}).get("stage") or "").strip()
            if checkpoint_stage == "waiting_profile_coalescing":
                continue
            lease_expires_at = str(worker.get("lease_expires_at") or "").strip()
            lease_owner = str(worker.get("lease_owner") or "").strip()
            if (
                not lease_expires_at
                or _is_sqlite_timestamp_expired(lease_expires_at)
                or worker_lease_owner_is_dead_local_process(lease_owner)
            ):
                workers.append(worker)
                if len(workers) >= max(1, int(limit or 100)):
                    break
        return workers

    def retire_agent_workers(
        self,
        *,
        worker_ids: list[int],
        status: str = "cancelled",
        reason: str = "",
        cleanup_metadata: dict[str, Any] | None = None,
    ) -> list[dict[str, Any]]:
        if self._control_plane_postgres_should_prefer_read("agent_worker_runs"):
            rows = self._call_control_plane_postgres_native(
                "retire_agent_workers",
                worker_ids=worker_ids,
                status=status,
                reason=reason,
                cleanup_metadata=cleanup_metadata or {},
            )
            return [self._agent_worker_from_row(row) for row in list(rows or [])]
        normalized_worker_ids = [int(worker_id) for worker_id in list(worker_ids or []) if int(worker_id or 0) > 0]
        if not normalized_worker_ids:
            return []
        normalized_status = str(status or "cancelled").strip().lower() or "cancelled"
        normalized_reason = str(reason or "").strip()
        cleanup_metadata = dict(cleanup_metadata or {})
        immutable_terminal_statuses = {"completed", "cancelled", "canceled", "superseded"}

        refreshed_ids: list[int] = []
        with self._lock, self._connection:
            for worker_id in normalized_worker_ids:
                row = self._connection.execute(
                    "SELECT * FROM agent_worker_runs WHERE worker_id = ? LIMIT 1",
                    (worker_id,),
                ).fetchone()
                if row is None:
                    continue
                current = self._agent_worker_from_row(row)
                current_status = str(current.get("status") or "").strip().lower()
                if current_status in immutable_terminal_statuses:
                    refreshed_ids.append(worker_id)
                    continue

                metadata = dict(current.get("metadata") or {})
                cleanup_payload = dict(metadata.get("cleanup") or {})
                cleanup_payload.update(
                    {
                        "reason": normalized_reason,
                        "status": normalized_status,
                        "cleaned_at": datetime.now(timezone.utc).isoformat(),
                    }
                )
                cleanup_payload.update(cleanup_metadata)
                metadata["cleanup"] = cleanup_payload

                output = dict(current.get("output") or {})
                output["cleanup"] = cleanup_payload

                self._connection.execute(
                    """
                    UPDATE agent_worker_runs
                    SET status = ?,
                        output_json = ?,
                        metadata_json = ?,
                        lease_owner = NULL,
                        lease_expires_at = NULL,
                        updated_at = CURRENT_TIMESTAMP
                    WHERE worker_id = ?
                    """,
                    (
                        normalized_status,
                        json.dumps(output, ensure_ascii=False),
                        json.dumps(metadata, ensure_ascii=False),
                        worker_id,
                    ),
                )
                refreshed_ids.append(worker_id)

        return [
            worker for worker_id in refreshed_ids if (worker := self.get_agent_worker(worker_id=worker_id)) is not None
        ]

    def claim_agent_worker(
        self,
        worker_id: int,
        *,
        lease_owner: str,
        lease_seconds: int,
    ) -> dict[str, Any] | None:
        if self._control_plane_postgres_should_prefer_read("agent_worker_runs"):
            row = self._call_control_plane_postgres_native(
                "claim_agent_worker",
                worker_id,
                lease_owner=lease_owner,
                lease_seconds=lease_seconds,
            )
            return self._agent_worker_from_row(row) if row is not None else None
        with self._lock, self._connection:
            current = self._connection.execute(
                "SELECT * FROM agent_worker_runs WHERE worker_id = ? LIMIT 1",
                (worker_id,),
            ).fetchone()
            if current is not None:
                current_worker = self._agent_worker_from_row(current)
                current_lease_owner = str(current_worker.get("lease_owner") or "").strip()
                current_lease_expires_at = str(current_worker.get("lease_expires_at") or "").strip()
                if (
                    current_lease_owner
                    and current_lease_expires_at
                    and not _is_sqlite_timestamp_expired(current_lease_expires_at)
                    and worker_lease_owner_is_dead_local_process(current_lease_owner)
                ):
                    self._connection.execute(
                        """
                        UPDATE agent_worker_runs
                        SET lease_owner = NULL,
                            lease_expires_at = NULL,
                            last_error = ?,
                            updated_at = CURRENT_TIMESTAMP
                        WHERE worker_id = ? AND lease_owner = ?
                        """,
                        (
                            f"Released dead local worker lease owner {current_lease_owner}",
                            worker_id,
                            current_lease_owner,
                        ),
                    )
            self._connection.execute(
                """
                UPDATE agent_worker_runs
                SET lease_owner = ?, lease_expires_at = datetime('now', ?), attempt_count = attempt_count + 1,
                    updated_at = CURRENT_TIMESTAMP
                WHERE worker_id = ?
                  AND (lease_expires_at IS NULL OR datetime(lease_expires_at) <= datetime('now'))
                """,
                (
                    lease_owner,
                    f"+{max(1, int(lease_seconds or 60))} seconds",
                    worker_id,
                ),
            )
            changed = self._connection.execute("SELECT changes()").fetchone()[0]
        if not changed:
            return None
        return self.get_agent_worker(worker_id=worker_id)

    def acquire_workflow_job_lease(
        self,
        job_id: str,
        *,
        lease_owner: str,
        lease_seconds: int = 900,
        lease_token: str = "",
    ) -> dict[str, Any]:
        normalized_job_id = str(job_id or "").strip()
        normalized_owner = str(lease_owner or "").strip()
        if not normalized_job_id or not normalized_owner:
            return {
                "job_id": normalized_job_id,
                "lease_owner": "",
                "lease_token": "",
                "lease_expires_at": "",
                "expired": True,
                "acquired": False,
            }
        normalized_token = (
            str(lease_token or "").strip()
            or sha1(f"{normalized_job_id}:{normalized_owner}".encode("utf-8")).hexdigest()
        )
        if self._control_plane_postgres_should_prefer_read("workflow_job_leases"):
            row = self._call_control_plane_postgres_native(
                "acquire_workflow_job_lease",
                normalized_job_id,
                lease_owner=normalized_owner,
                lease_seconds=lease_seconds,
                lease_token=normalized_token,
            )
            payload = self._workflow_job_lease_from_row(row)
            return {
                **payload,
                "acquired": bool(
                    payload
                    and str(payload.get("lease_owner") or "") == normalized_owner
                    and str(payload.get("lease_token") or "") == normalized_token
                ),
            }
        ttl_seconds = max(5, int(lease_seconds or 0))
        with self._lock, self._connection:
            self._connection.execute(
                """
                INSERT INTO workflow_job_leases (
                    job_id,
                    lease_owner,
                    lease_token,
                    lease_expires_at
                ) VALUES (?, ?, ?, datetime('now', ?))
                ON CONFLICT(job_id) DO UPDATE SET
                    lease_owner = excluded.lease_owner,
                    lease_token = excluded.lease_token,
                    lease_expires_at = excluded.lease_expires_at,
                    updated_at = CURRENT_TIMESTAMP
                WHERE datetime(workflow_job_leases.lease_expires_at) <= datetime('now')
                   OR workflow_job_leases.lease_owner = excluded.lease_owner
                   OR workflow_job_leases.lease_token = excluded.lease_token
                """,
                (
                    normalized_job_id,
                    normalized_owner,
                    normalized_token,
                    f"+{ttl_seconds} seconds",
                ),
            )
            changed = int(self._connection.execute("SELECT changes()").fetchone()[0] or 0)
            lease_row = self._connection.execute(
                """
                SELECT * FROM workflow_job_leases
                WHERE job_id = ?
                """,
                (normalized_job_id,),
            ).fetchone()
        payload = self._workflow_job_lease_from_row(lease_row)
        return {
            **payload,
            "acquired": bool(
                changed
                and payload
                and str(payload.get("lease_owner") or "") == normalized_owner
                and str(payload.get("lease_token") or "") == normalized_token
            ),
        }

    def get_workflow_job_lease(self, job_id: str) -> dict[str, Any] | None:
        normalized_job_id = str(job_id or "").strip()
        if not normalized_job_id:
            return None
        if self._control_plane_postgres_should_prefer_read("workflow_job_leases"):
            row = self._call_control_plane_postgres_native("get_workflow_job_lease", normalized_job_id)
            return self._workflow_job_lease_from_row(row) if row is not None else None
        with self._lock:
            row = self._connection.execute(
                """
                SELECT * FROM workflow_job_leases
                WHERE job_id = ?
                """,
                (normalized_job_id,),
            ).fetchone()
        if row is None:
            return None
        return self._workflow_job_lease_from_row(row)

    def renew_workflow_job_lease(
        self,
        job_id: str,
        *,
        lease_owner: str,
        lease_seconds: int,
        lease_token: str = "",
    ) -> dict[str, Any] | None:
        normalized_job_id = str(job_id or "").strip()
        normalized_owner = str(lease_owner or "").strip()
        normalized_token = str(lease_token or "").strip()
        if not normalized_job_id or not normalized_owner:
            return None
        if self._control_plane_postgres_should_prefer_read("workflow_job_leases"):
            row = self._call_control_plane_postgres_native(
                "renew_workflow_job_lease",
                normalized_job_id,
                lease_owner=normalized_owner,
                lease_seconds=lease_seconds,
                lease_token=normalized_token,
            )
            if row is not None:
                return self._workflow_job_lease_from_row(row)
            return None
        clauses = ["job_id = ?", "lease_owner = ?"]
        params: list[Any] = [f"+{max(5, int(lease_seconds or 0))} seconds", normalized_job_id, normalized_owner]
        if normalized_token:
            clauses.append("lease_token = ?")
            params.append(normalized_token)
        with self._lock, self._connection:
            self._connection.execute(
                f"""
                UPDATE workflow_job_leases
                SET lease_expires_at = datetime('now', ?),
                    updated_at = CURRENT_TIMESTAMP
                WHERE {" AND ".join(clauses)}
                """,
                tuple(params),
            )
        return self.get_workflow_job_lease(normalized_job_id)

    def release_workflow_job_lease(
        self,
        job_id: str,
        *,
        lease_owner: str = "",
        lease_token: str = "",
    ) -> None:
        normalized_job_id = str(job_id or "").strip()
        normalized_owner = str(lease_owner or "").strip()
        normalized_token = str(lease_token or "").strip()
        if not normalized_job_id:
            return
        if self._control_plane_postgres_should_prefer_read("workflow_job_leases"):
            self._call_control_plane_postgres_native(
                "release_workflow_job_lease",
                normalized_job_id,
                lease_owner=normalized_owner,
                lease_token=normalized_token,
            )
            return
        with self._lock, self._connection:
            if normalized_owner and normalized_token:
                self._connection.execute(
                    """
                    DELETE FROM workflow_job_leases
                    WHERE job_id = ? AND lease_owner = ? AND lease_token = ?
                    """,
                    (normalized_job_id, normalized_owner, normalized_token),
                )
                return
            if normalized_owner:
                self._connection.execute(
                    """
                    DELETE FROM workflow_job_leases
                    WHERE job_id = ? AND lease_owner = ?
                    """,
                    (normalized_job_id, normalized_owner),
                )
                return
            if normalized_token:
                self._connection.execute(
                    """
                    DELETE FROM workflow_job_leases
                    WHERE job_id = ? AND lease_token = ?
                    """,
                    (normalized_job_id, normalized_token),
                )
                return
            self._connection.execute(
                """
                DELETE FROM workflow_job_leases
                WHERE job_id = ?
                """,
                (normalized_job_id,),
            )

    def upsert_workflow_recovery_intent(
        self,
        job_id: str,
        *,
        classification: str = "",
        params: dict[str, Any] | None = None,
        requested_by: str = "",
    ) -> dict[str, Any]:
        """Read-path write of a durable per-job recovery-takeover intent.

        ``job_id`` is the PRIMARY KEY; concurrent upserts for distinct jobs keep
        independent rows. ``ON CONFLICT(job_id) DO UPDATE`` is latest-wins and
        resets the row to ``status='pending'`` with leases cleared so a stale
        consumed/claimed row is re-armed by a fresh takeover request.
        """

        normalized_job_id = str(job_id or "").strip()
        if not normalized_job_id:
            return {}
        if self._control_plane_postgres_should_prefer_read("workflow_recovery_intents"):
            row = self._call_control_plane_postgres_native(
                "upsert_workflow_recovery_intent",
                normalized_job_id,
                classification=classification,
                params=dict(params or {}),
                requested_by=requested_by,
            )
            if row is not None:
                return self._workflow_recovery_intent_from_row(row)
            if self._control_plane_postgres_should_skip_sqlite_fallback("workflow_recovery_intents"):
                return {}
        now = _utc_now_timestamp()
        params_json = json.dumps(_json_safe_payload(dict(params or {})), ensure_ascii=False)
        with self._lock, self._connection:
            self._connection.execute(
                """
                INSERT INTO workflow_recovery_intents (
                    job_id,
                    classification,
                    status,
                    requested_at,
                    requested_by,
                    params_json,
                    lease_owner,
                    lease_expires_at,
                    claimed_at,
                    schema_version,
                    created_at,
                    updated_at
                ) VALUES (?, ?, 'pending', ?, ?, ?, '', '', '', 'workflow_recovery_intent_v1', ?, ?)
                ON CONFLICT(job_id) DO UPDATE SET
                    classification = excluded.classification,
                    status = 'pending',
                    requested_at = excluded.requested_at,
                    requested_by = excluded.requested_by,
                    params_json = excluded.params_json,
                    lease_owner = '',
                    lease_expires_at = '',
                    claimed_at = '',
                    updated_at = excluded.updated_at
                """,
                (
                    normalized_job_id,
                    str(classification or ""),
                    now,
                    str(requested_by or ""),
                    params_json,
                    now,
                    now,
                ),
            )
            row = self._connection.execute(
                "SELECT * FROM workflow_recovery_intents WHERE job_id = ? LIMIT 1",
                (normalized_job_id,),
            ).fetchone()
        self._mirror_control_plane_row("workflow_recovery_intents", row)
        return self._workflow_recovery_intent_from_row(row)

    def claim_workflow_recovery_intents(
        self,
        *,
        lease_owner: str,
        lease_seconds: int = 300,
        limit: int = 1,
    ) -> list[dict[str, Any]]:
        """Single-winner claim of claimable recovery intents (drain phase).

        Copies the ``claim_job_materialization_item`` single-winner semantics:
        the conditional ``UPDATE ... WHERE <claimable>`` guarantees two
        concurrent daemon ticks claim disjoint sets — a row whose status is
        flipped to ``claimed`` (with a fresh future lease) by one tick no longer
        matches the predicate for the other. Claimable = ``status='pending'`` OR
        an EXPIRED-lease ``status='claimed'`` row, so a takeover_failed intent
        left claimed (and a row whose claiming daemon crashed) is reclaimed once
        its lease expires — without this, a failed/crashed claim would strand the
        intent forever (the drain leaves it claimed on retryable failure).
        """

        normalized_owner = str(lease_owner or "").strip()
        if not normalized_owner:
            return []
        normalized_limit = max(1, int(limit or 1))
        if self._control_plane_postgres_should_prefer_read("workflow_recovery_intents"):
            rows = self._call_control_plane_postgres_native(
                "claim_workflow_recovery_intents",
                lease_owner=normalized_owner,
                lease_seconds=max(1, int(lease_seconds or 300)),
                limit=normalized_limit,
            )
            if rows is not None:
                return [self._workflow_recovery_intent_from_row(row) for row in rows]
            if self._control_plane_postgres_should_skip_sqlite_fallback("workflow_recovery_intents"):
                return []
        now = _utc_now_timestamp()
        claimed: list[Any] = []
        with self._lock, self._connection:
            candidate_rows = self._connection.execute(
                """
                SELECT job_id FROM workflow_recovery_intents
                WHERE status = 'pending'
                   OR (status = 'claimed'
                       AND lease_expires_at != ''
                       AND datetime(lease_expires_at) <= datetime('now'))
                ORDER BY requested_at, job_id
                LIMIT ?
                """,
                (normalized_limit,),
            ).fetchall()
            for candidate in candidate_rows:
                candidate_job_id = str(candidate["job_id"] or "")
                if not candidate_job_id:
                    continue
                self._connection.execute(
                    """
                    UPDATE workflow_recovery_intents
                    SET status = 'claimed',
                        lease_owner = ?,
                        lease_expires_at = datetime('now', ?),
                        claimed_at = ?,
                        updated_at = ?
                    WHERE job_id = ?
                      AND (status = 'pending'
                           OR (status = 'claimed'
                               AND lease_expires_at != ''
                               AND datetime(lease_expires_at) <= datetime('now')))
                    """,
                    (
                        normalized_owner,
                        f"+{max(1, int(lease_seconds or 300))} seconds",
                        now,
                        now,
                        candidate_job_id,
                    ),
                )
                if not int(self._connection.execute("SELECT changes()").fetchone()[0] or 0):
                    continue
                row = self._connection.execute(
                    "SELECT * FROM workflow_recovery_intents WHERE job_id = ? LIMIT 1",
                    (candidate_job_id,),
                ).fetchone()
                if row is not None:
                    claimed.append(row)
        for row in claimed:
            self._mirror_control_plane_row("workflow_recovery_intents", row)
        return [self._workflow_recovery_intent_from_row(row) for row in claimed]

    def mark_workflow_recovery_intent_consumed(
        self, job_id: str, *, lease_owner: str = "", claimed_at: str = ""
    ) -> dict[str, Any]:
        normalized_job_id = str(job_id or "").strip()
        if not normalized_job_id:
            return {}
        normalized_lease_owner = str(lease_owner or "").strip()
        normalized_claimed_at = str(claimed_at or "").strip()
        if self._control_plane_postgres_should_prefer_read("workflow_recovery_intents"):
            row = self._call_control_plane_postgres_native(
                "mark_workflow_recovery_intent_consumed",
                normalized_job_id,
                normalized_lease_owner,
                normalized_claimed_at,
            )
            if row is not None:
                return self._workflow_recovery_intent_from_row(row)
            if self._control_plane_postgres_should_skip_sqlite_fallback("workflow_recovery_intents"):
                return {}
        with self._lock, self._connection:
            # Consume only the exact row this daemon claimed (status='claimed'
            # AND lease_owner AND claimed_at). If a newer upsert re-armed the row
            # to 'pending' between claim and consume, this UPDATE matches nothing
            # and the fresh intent survives for the next drain (no stale-claim
            # clobber of a newer same-job intent).
            self._connection.execute(
                """
                UPDATE workflow_recovery_intents
                SET status = 'consumed',
                    lease_owner = '',
                    lease_expires_at = '',
                    updated_at = ?
                WHERE job_id = ?
                  AND status = 'claimed'
                  AND lease_owner = ?
                  AND claimed_at = ?
                """,
                (_utc_now_timestamp(), normalized_job_id, normalized_lease_owner, normalized_claimed_at),
            )
            row = self._connection.execute(
                "SELECT * FROM workflow_recovery_intents WHERE job_id = ? LIMIT 1",
                (normalized_job_id,),
            ).fetchone()
        self._mirror_control_plane_row("workflow_recovery_intents", row)
        return self._workflow_recovery_intent_from_row(row)

    def get_workflow_recovery_intent(self, job_id: str) -> dict[str, Any]:
        normalized_job_id = str(job_id or "").strip()
        if not normalized_job_id:
            return {}
        if self._control_plane_postgres_should_prefer_read("workflow_recovery_intents"):
            select_one = getattr(self._control_plane_postgres, "select_one", None)
            if callable(select_one):
                try:
                    row = select_one(
                        "workflow_recovery_intents",
                        where_sql="job_id = %s",
                        params=[normalized_job_id],
                    )
                except Exception:
                    row = None
                if row is not None:
                    return self._workflow_recovery_intent_from_row(row)
            if self._control_plane_postgres_should_skip_sqlite_fallback("workflow_recovery_intents"):
                return {}
        with self._lock:
            row = self._connection.execute(
                "SELECT * FROM workflow_recovery_intents WHERE job_id = ? LIMIT 1",
                (normalized_job_id,),
            ).fetchone()
        return self._workflow_recovery_intent_from_row(row)

    def _workflow_recovery_intent_from_row(self, row: Any) -> dict[str, Any]:
        if row is None:
            return {}
        lease_expires_at = str(_row_value(row, "lease_expires_at", "") or "")
        return {
            "job_id": str(_row_value(row, "job_id", "") or ""),
            "classification": str(_row_value(row, "classification", "") or ""),
            "status": str(_row_value(row, "status", "") or ""),
            "requested_at": str(_row_value(row, "requested_at", "") or ""),
            "requested_by": str(_row_value(row, "requested_by", "") or ""),
            "params": _loads_json_dict(_row_value(row, "params_json", "{}")),
            "lease_owner": str(_row_value(row, "lease_owner", "") or ""),
            "lease_expires_at": lease_expires_at,
            "claimed_at": str(_row_value(row, "claimed_at", "") or ""),
            "schema_version": str(
                _row_value(row, "schema_version", "workflow_recovery_intent_v1")
                or "workflow_recovery_intent_v1"
            ),
            "created_at": str(_row_value(row, "created_at", "") or ""),
            "updated_at": str(_row_value(row, "updated_at", "") or ""),
        }

    def append_workflow_event(
        self,
        *,
        workflow_run_id: str,
        event_family: str,
        event_type: str,
        idempotency_key: str,
        operation_id: str = "",
        command_id: str = "",
        activity_attempt_id: str = "",
        sequence_number: int = 0,
        occurred_at: str = "",
        actor: str = "",
        source: str = "",
        payload: dict[str, Any] | None = None,
        artifact_refs: list[Any] | tuple[Any, ...] | None = None,
        schema_version: str = "workflow_event_v1",
    ) -> dict[str, Any]:
        self._require_postgres_for_durable_runtime("workflow_events")
        normalized_run_id = str(workflow_run_id or "").strip()
        normalized_family = str(event_family or "").strip()
        normalized_type = str(event_type or "").strip()
        normalized_idempotency = str(idempotency_key or "").strip()
        if not normalized_run_id or not normalized_family or not normalized_type or not normalized_idempotency:
            return {}
        now = _utc_now_timestamp()
        row_payload = {
            "event_id": "",
            "workflow_run_id": normalized_run_id,
            "operation_id": str(operation_id or "").strip(),
            "command_id": str(command_id or "").strip(),
            "activity_attempt_id": str(activity_attempt_id or "").strip(),
            "event_family": normalized_family,
            "event_type": normalized_type,
            "sequence_number": max(0, int(sequence_number or 0)),
            "idempotency_key": normalized_idempotency,
            "occurred_at": str(occurred_at or now).strip(),
            "recorded_at": now,
            "actor": str(actor or "").strip(),
            "source": str(source or "").strip(),
            "payload_json": json.dumps(_json_safe_payload(payload or {}), ensure_ascii=False),
            "artifact_refs_json": json.dumps(_json_safe_payload(list(artifact_refs or [])), ensure_ascii=False),
            "schema_version": str(schema_version or "workflow_event_v1").strip(),
            "created_at": now,
        }
