def _fallback_record_token(*values: Any) -> str:
    raw = "|".join(str(value or "").strip().lower() for value in values if str(value or "").strip())
    if not raw:
        raw = "unknown"
    return sha1(raw.encode("utf-8")).hexdigest()[:16]


